{
  "avaliacoes": [
    {
      "id": "E68ff9b835100fc73",
      "pertinente": true,
      "tipo": "norma",
      "achados": [
        {
          "proposicao": "A inspeção de segurança funcional é apresentada como parte de um conjunto de medidas para minimizar risco e prevenir eventos perigosos, sendo avaliada em relação ao padrão de referência BS EN 61511.",
          "trechos": [
            "E68ff9b835100fc73:0:699"
          ],
          "condicoes": [
            "Contexto de inspeções de segurança funcional em instalações offshore sob a jurisdição indicada pela fonte",
            "Avaliação de conformidade demonstrada pelo duty holder frente ao padrão de referência citado"
          ],
          "limites": [
            "Refere-se a guia de inspeção estrangeiro, não a requisito brasileiro por si só",
            "O trecho não trata especificamente de backups, restauração testada ou autenticidade de dados"
          ]
        },
        {
          "proposicao": "A fonte relaciona a robustez da segurança funcional a elementos operacionais como limites operacionais seguros, gestão desses limites, gestão de alarmes, overrides e inhibits, além de outras medidas de prevenção.",
          "trechos": [
            "E68ff9b835100fc73:0:699",
            "E68ff9b835100fc73:699:1396"
          ],
          "condicoes": [
            "No escopo da implementação adequada de abordagem robusta de segurança funcional",
            "Aplicável às fases de projeto e operação mencionadas no guia"
          ],
          "limites": [
            "O trecho apenas enumera temas de inspeção e não detalha critérios técnicos de seleção, teste ou aceitação",
            "Não explicita lógicas de SIS específicas nem procedimentos de recuperação após incidente"
          ]
        },
        {
          "proposicao": "Quando componentes de SIF não funcionam como projetado, a fonte remete a avaliação de risco operacional em condições anormais e indica interface com guia específico de cibersegurança para IACS.",
          "trechos": [
            "E68ff9b835100fc73:1396:2085"
          ],
          "condicoes": [
            "Cenários em que componentes de funções instrumentadas de segurança não estejam operando conforme o projeto",
            "Uso articulado entre inspeção de segurança funcional, avaliação de risco operacional e inspeção de cibersegurança"
          ],
          "limites": [
            "A fonte não descreve como restaurar, testar ou validar essas funções após falha",
            "Não aborda integridade ou autenticidade de dados de forma direta nos trechos fornecidos"
          ]
        }
      ]
    },
    {
      "id": "E2d81a6a16a58e987",
      "pertinente": true,
      "tipo": "norma",
      "achados": [
        {
          "proposicao": "O guia define que inspeções de cibersegurança para IACS devem apoiar verificação consistente e efetiva dos arranjos de cibersegurança de operadores e duty holders em instalações offshore e outros ambientes regulados citados.",
          "trechos": [
            "E2d81a6a16a58e987:0:698",
            "E2d81a6a16a58e987:1391:2091"
          ],
          "condicoes": [
            "Contexto do guia de inspeção do HSE/OSDR para UKCS e demais regimes regulatórios mencionados",
            "Aplicável a inspeções iniciais e subsequentes conforme categorização do guia"
          ],
          "limites": [
            "Norma/guia estrangeiro, não requisito brasileiro automático",
            "Os trechos não detalham mecanismos de backup, restauração ou teste de recuperação"
          ]
        },
        {
          "proposicao": "A fonte adota abordagem proporcional e direcionada por categorias de inspeção, incluindo autoavaliações e planos de melhoria para instalações reguladas e intervenções planejadas posteriores.",
          "trechos": [
            "E2d81a6a16a58e987:698:1391",
            "E2d81a6a16a58e987:1391:2091"
          ],
          "condicoes": [
            "Uso de categorias de inspeção para instalações NIS e não NIS segundo o guia",
            "Consideração de respostas de autoavaliação e improvement plans como insumos"
          ],
          "limites": [
            "Os critérios detalhados de seleção e aceitação não aparecem integralmente nos trechos",
            "Não trata explicitamente de recuperação segura de sistemas críticos após falha ou incidente"
          ]
        },
        {
          "proposicao": "O objetivo primário de OG86, conforme citado, é permitir verificar a adequação do sistema de gestão de cibersegurança de IACS, incluindo gestão de competências e efetividade de contramedidas de cibersegurança.",
          "trechos": [
            "E2d81a6a16a58e987:1391:2091",
            "E2d81a6a16a58e987:2091:2518"
          ],
          "condicoes": [
            "Aplicável a locais com potencial de grandes acidentes e operadores de serviços essenciais cobertos pelo regime citado",
            "No contexto de inspeção da adequação do sistema de gestão de cibersegurança"
          ],
          "limites": [
            "O trecho não evidencia comprovação empírica de efetividade das contramedidas em campo",
            "Não explicita autenticidade de dados nem preservação de lógicas de SIS"
          ]
        }
      ]
    },
    {
      "id": "Ea3d79d3ac748d62d",
      "pertinente": true,
      "tipo": "norma",
      "achados": [
        {
          "proposicao": "A fonte enquadra IACS de modo amplo, incluindo sistemas básicos de controle de processo, funções de camada independente de proteção, sistemas de segurança, sistemas elétricos de controle/aquisição de dados e sistemas de informação e negócios conectados pela infraestrutura de rede do IACS.",
          "trechos": [
            "Ea3d79d3ac748d62d:0:700",
            "Ea3d79d3ac748d62d:700:1390"
          ],
          "condicoes": [
            "No escopo do guia de cibersegurança para IACS citado",
            "Quando os sistemas estejam conectados pela infraestrutura de rede do IACS"
          ],
          "limites": [
            "É definição de escopo do guia, não descrição de mecanismo de proteção específico",
            "Não detalha critérios técnicos para preservar autenticidade de dados ou restaurar sistemas"
          ]
        },
        {
          "proposicao": "Para offshore, o escopo do IACS pode incluir também sistemas marítimos, de perfuração e de monitoramento de movimento de helicóptero.",
          "trechos": [
            "Ea3d79d3ac748d62d:700:1390"
          ],
          "condicoes": [
            "Aplicação offshore segundo o guia",
            "Inclusão adicional para sistemas associados mencionados pela fonte"
          ],
          "limites": [
            "O trecho usa formulação de possibilidade ('may also include'), não de inclusão obrigatória em qualquer instalação",
            "Não é específico para FPSO nem para funções de backup e recuperação"
          ]
        },
        {
          "proposicao": "Nas instalações reguladas por NIS citadas, a autoavaliação baseada no Cyber Assessment Framework e o plano de melhoria decorrente são tratados como ponto de partida para inspeções amostrais posteriores.",
          "trechos": [
            "Ea3d79d3ac748d62d:1390:2090",
            "Ea3d79d3ac748d62d:2090:2378"
          ],
          "condicoes": [
            "Quando o operador de serviço essencial realiza a autoavaliação e entrega plano de melhoria conforme o regime mencionado",
            "Uso do resultado como base para inspeção por amostragem"
          ],
          "limites": [
            "Refere-se a arranjo regulatório estrangeiro específico",
            "Não explicita requisitos de backup, restauração testada, proteção de lógicas SIS ou autenticidade de dados"
          ]
        }
      ]
    },
    {
      "id": "E55b8a6205c6a682e",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "Em aplicações SCADA, a padronização de dados é apresentada como desejável para viabilizar análise, sendo o próprio sistema SCADA apontado como o ponto mais próximo da fonte de dados onde isso pode ser feito quando a padronização na camada de controle é limitada.",
          "trechos": [
            "E55b8a6205c6a682e:0:696",
            "E55b8a6205c6a682e:696:1394"
          ],
          "condicoes": [
            "Quando há diversidade de modelos de dados entre controladores de diferentes fornecedores",
            "Quando a padronização na camada de controle é limitada"
          ],
          "limites": [
            "A fonte fala em padronização e análise de dados, não em autenticação criptográfica ou prova de integridade",
            "Não trata de backups, restauração testada ou recuperação segura após incidente"
          ]
        },
        {
          "proposicao": "A diversidade de mapas de dados de fornecedores e a coexistência de modelos customizados são associadas a dificuldades para convenções de nomenclatura, padrões de HMI e comparação entre ativos sem retrabalho de dados.",
          "trechos": [
            "E55b8a6205c6a682e:0:696"
          ],
          "condicoes": [
            "Ambientes com múltiplos controladores de campo e modelos de dados distintos",
            "Uso de aplicações SCADA, historiadores e HMIs"
          ],
          "limites": [
            "É explicação técnica genérica, sem validação experimental explícita nos trechos",
            "Não especifica consequências diretas sobre SIS ou continuidade operacional"
          ]
        },
        {
          "proposicao": "A fonte descreve uso de historiador temporal para armazenamento de dados e HMIs com situational awareness como interfaces, indicando composição informacional do nível supervisório.",
          "trechos": [
            "E55b8a6205c6a682e:0:696"
          ],
          "condicoes": [
            "No contexto de aplicações do sistema SCADA para gestão de alarmes e supervisão",
            "Quando se deseja armazenar dados e prover interfaces ao usuário"
          ],
          "limites": [
            "Não informa requisitos de retenção, integridade, redundância ou restauração do historiador",
            "Não aborda segurança cibernética desses componentes"
          ]
        }
      ]
    },
